/**
 * Button: an accessible action.
 * @param {object} props
 * @param {React.ReactNode} props.children   Visible label. Required.
 * @param {() => void} props.onPress          Called on click, Enter or Space. Required.
 * @param {"primary" | "secondary" | "danger"} [props.variant="secondary"]
 * @param {boolean} [props.disabled=false]    Disabled buttons can't be pressed or focused.
 */
export function Button({ children, onPress, variant = "secondary", disabled = false }) {
  return (
    <button
      type="button"                          // constraint: a real button, not a div.
      className={`btn btn--${variant}`}
      onClick={onPress}
      disabled={disabled}
    >
      {children}
    </button>
  );
}

<Button onPress={save} variant="primary">Save lesson</Button>
